draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // brain
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 50 * Math.sin(t), H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 100, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 120);
  ctx.lineTo(W/2, H/2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 130);
  ctx.lineTo(W/2 - 20, H/2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 130);
  ctx.lineTo(W/2 + 20, H/2 + 120);
  ctx.stroke();

  // eye
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 5 + 5 * Math.sin(t), H/2 + 105, 5, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
